-- Cloudflare D1 schema for the EKY Directory.
-- Create once:  npx wrangler d1 create eky-directory
-- Apply:        npx wrangler d1 execute eky-directory --remote --file db/schema.sql
-- Load data:    npx wrangler d1 execute eky-directory --remote --file db/seed-el-salvador.sql   (generated by the build)
CREATE TABLE IF NOT EXISTS entries (
  id TEXT PRIMARY KEY,
  country TEXT NOT NULL,
  kind TEXT NOT NULL,            -- organization | person
  category TEXT NOT NULL,
  name TEXT NOT NULL,
  type TEXT,
  department TEXT,
  tags TEXT,                     -- pipe separated
  search_text TEXT,
  json TEXT NOT NULL,            -- full public record, same shape as /api/v1/entries/{id}.json
  last_checked TEXT,
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE INDEX IF NOT EXISTS idx_entries_country_cat ON entries (country, category);
CREATE INDEX IF NOT EXISTS idx_entries_department ON entries (department);

-- Later: owner edits and claims (not used yet)
CREATE TABLE IF NOT EXISTS change_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  entry_id TEXT,
  requested_by TEXT,
  payload TEXT NOT NULL,
  status TEXT DEFAULT 'pending',
  created_at TEXT DEFAULT (datetime('now'))
);
